der-radius:10px;background:white;padding:11px 13px;outline:none}input:focus{border-color:var(--green);box-shadow:0 0 0 3px rgba(49,92,75,.11)}button{border:0;border-radius:10px;padding:11px 17px;cursor:pointer;font-weight:750}.primary{background:var(--green);color:white}.secondary{background:#e7e8df;color:var(--ink)}.suggestions{display:flex;flex-wrap:wrap;gap:8px}.suggestion{border:1px solid var(--line);background:white;color:var(--ink)}.suggestion.selected{background:var(--lime);border-color:#b6c178;color:var(--green)}.select-list{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.select-item{display:flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:9px;padding:10px;background:white}.select-item input{width:auto}.create{margin-top:12px}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.notice{display:none;margin-top:15px;border-radius:10px;background:#edf2d4;color:var(--green);padding:11px 14px;font-weight:700}@media(max-width:560px){.bookmark{grid-template-columns:1fr}.image{min-height:90px}.select-list{grid-template-columns:1fr}}
