*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:var(--paper);color:var(--ink);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}button,input,textarea{font:inherit;color:inherit}button,a{touch-action:manipulation}.plain{border:0;background:transparent;cursor:pointer}.topbar{position:sticky;top:0;z-index:10;height:72px;display:flex;align-items:center;justify-content:space-between;padding:0 5vw;border-bottom:1px solid var(--line);background:rgba(244,241,233,.95);backdrop-filter:blur(10px)}.brand{display:flex;align-items:center;gap:11px;padding:0;font:700 23px Georgia,serif}.brand-mark{position:relative;width:28px;height:34px;border-radius:5px 5px 10px 10px;background:var(--green)}.brand-mark:after{content:"";position:absolute;top:8px;left:10px;width:8px;height:8px;border-radius:50%;background:var(--lime)}.button{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:10px;padding:11px 17px;text-decoration:none;cursor:pointer;font-weight:750}.button:disabled{opacity:.55;cursor:default}.primary{background:var(--green);color:white}.primary:hover:not(:disabled){background:var(--green-dark)}.secondary{background:#e8e8df;color:var(--ink)}.app-shell{display:grid;grid-template-columns:200px minmax(0,1fr);gap:48px;width:min(1160px,92vw);margin:50px auto}.sidebar{position:sticky;top:112px;align-self:start}.main-nav,.tag-nav{display:grid;gap:5px}.nav-item{display:flex;justify-content:space-between;gap:14px;width:100%;padding:10px 12px;border:0;border-radius:9px;background:transparent;cursor:pointer;text-align:left}.nav-item:hover{background:#e9e7df}.nav-item.active{background:var(--green);color:white}.nav-item span:last-child{opacity:.68}.sidebar-label{margin:25px 12px 9px;color:var(--muted);font-size:11px;font-weight:850;letter-spacing:.09em;text-transform:uppercase}.collection{min-width:0}.collection-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:23px}.collection-head h1{margin:0;font:700 42px/1.05 Georgia,serif;letter-spacing:-1.2px}.collection-head p{margin:8px 0 0;color:var(--muted)}.result-count{color:var(--muted);white-space:nowrap}.search-wrap{position:relative;margin-bottom:25px}.search-wrap>span{position:absolute;left:16px;top:10px;color:var(--muted);font-size:23px}.search-wrap input{width:100%;padding:13px 47px;border:1px solid #bfc1b8;border-radius:12px;background:white;outline:none;font-size:16px}.search-wrap input:focus,input:focus,textarea:focus{border-color:var(--green);box-shadow:0 0 0 3px rgba(49,92,75,.11)}.clear-search{position:absolute;right:11px;top:8px;color:var(--muted);font-size:22px}.notice{margin-bottom:18px;padding:12px 15px;border:1px solid #d4dda0;border-radius:10px;background:#eef2d5;color:var(--green);font-weight:700}.bookmark-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.bookmark-card{min-width:0;overflow:hidden;border:1px solid var(--line);border-radius:15px;background:var(--card);box-shadow:0 10px 27px rgba(47,57,48,.05)}.card-image{height:125px;display:flex;align-items:end;padding:15px;background:linear-gradient(145deg,#294b40,#628169 65%,#cad79c);color:white;font:700 19px Georgia,serif;background-position:center;background-size:cover}.card-body{padding:18px}.site-line{display:flex;align-items:center;gap:8px;min-width:0;color:var(--muted);font-size:12px}.site-line img{width:21px;height:21px;border-radius:5px;object-fit:contain}.site-fallback{width:21px;height:21px;display:grid;place-items:center;border-radius:5px;background:var(--green);color:white;font-weight:800}.bookmark-card h2{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;min-height:50px;margin:8px 0 5px;font:700 21px/1.2 Georgia,serif}.title-link{border:0;background:transparent;padding:0;text-align:left;cursor:pointer;font:inherit}.title-link:hover{text-decoration:underline;text-decoration-color:var(--green);text-underline-offset:4px}.card-description{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;min-height:42px;margin:0 0 13px;color:var(--muted);font-size:14px}.note-match{margin:0 0 12px;padding:8px 10px;border-radius:8px;background:#eef2d5;color:var(--green);font-size:13px}.tag-row{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}.tag-pill{border:0;border-radius:99px;padding:4px 9px;background:#eaeee5;color:var(--green);font-size:12px;font-weight:750}.card-actions{display:flex;flex-wrap:wrap;gap:8px}.card-action{border:1px solid var(--line);border-radius:8px;padding:7px 10px;background:white;cursor:pointer;color:var(--green);font-size:13px;font-weight:750}.card-action.active{border-color:#bcc77d;background:var(--lime)}.card-action.archive{color:var(--muted)}.empty-state{min-height:370px;place-items:center;padding:45px;border:1px dashed #c8c9bf;border-radius:16px;background:var(--card);text-align:center}.empty-state:not([hidden]){display:grid}.empty-icon{width:51px;height:51px;display:grid;place-items:center;margin:0 auto 16px;border-radius:50%;background:var(--lime);color:var(--green);font-size:23px;font-weight:900}.empty-state h2{margin:0 0 7px;font:700 25px Georgia,serif}.empty-state p{max-width:430px;margin:0 auto 19px;color:var(--muted)}.modal{width:min(760px,94vw);max-height:92vh;padding:0;border:0;border-radius:18px;background:transparent}.modal::backdrop{background:rgba(25,32,28,.55);backdrop-filter:blur(3px)}.modal-frame{max-height:92vh;overflow:auto;margin:0;padding:25px;border:1px solid var(--line);border-radius:18px;background:var(--card);box-shadow:0 24px 70px rgba(0,0,0,.22)}.modal-head{display:flex;align-items:start;justify-content:space-between;gap:18px;margin-bottom:22px}.modal-head h2{margin:0;font:700 30px/1.15 Georgia,serif}.overline{margin:0 0 5px;color:var(--green);font-size:11px;font-weight:850;letter-spacing:.09em;text-transform:uppercase}.close{padding:0 4px;color:var(--muted);font-size:28px;line-height:1}label,legend{display:block;margin-bottom:7px;font-size:12px;font-weight:850;letter-spacing:.07em;text-transform:uppercase}label span{font-weight:500;letter-spacing:0;text-transform:none}input,textarea{width:100%;padding:11px 13px;border:1px solid #bfc1b8;border-radius:9px;background:white;outline:none}textarea{resize:vertical}.url-row,.new-tag-row{display:flex;gap:9px}.field-message,.helper{margin:7px 0 0;color:var(--muted);font-size:13px}.field-message.error{color:var(--danger);font-weight:700}.fetch-warning,.duplicate-note{display:grid;margin-bottom:18px;padding:13px 15px;border:1px solid #ead39c;border-radius:10px;background:var(--warn);color:#64491b}.fetch-warning strong,.duplicate-note strong{color:#845812}.preview-row{display:grid;grid-template-columns:130px 1fr;gap:16px;margin-bottom:21px}.preview-image{min-height:95px;display:flex;align-items:end;padding:13px;border-radius:11px;background:linear-gradient(145deg,#294b40,#628169,#cad79c);background-position:center;background-size:cover;color:white;font:700 16px Georgia,serif}.form-grid{display:grid;gap:15px}fieldset{margin:0;padding:0;border:0}.tag-choices{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}.tag-choice{display:flex;align-items:center;gap:6px;margin:0;padding:7px 10px;border:1px solid var(--line);border-radius:9px;background:white;font-size:13px;font-weight:650;letter-spacing:0;text-transform:none}.tag-choice:has(input:checked){border-color:#bac67c;background:var(--lime);color:var(--green)}.tag-choice input,.later-check input{width:auto;box-shadow:none}.later-check{display:flex;align-items:center;gap:9px;margin:0;font-size:14px;letter-spacing:0;text-transform:none}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.dialog-actions.split{justify-content:space-between}.detail-image{width:100%;max-height:300px;object-fit:cover;border-radius:12px}.detail-description{color:var(--muted);white-space:pre-wrap}.detail-tags{display:flex;flex-wrap:wrap;gap:7px}.note-block{margin-top:20px;padding:16px 18px;border-left:4px solid var(--lime);border-radius:0 10px 10px 0;background:#f0f3df}.note-block p:last-child{margin:0;white-space:pre-wrap}.toast{position:fixed;left:50%;bottom:26px;z-index:30;transform:translate(-50%,20px);padding:11px 17px;border-radius:99px;background:var(--ink);color:white;box-shadow:0 8px 25px rgba(0,0,0,.2);font-weight:700;opacity:0;pointer-events:none;transition:.18s}.toast.show{transform:translate(-50%,0);opacity:1}
@media(max-width:800px){.app-shell{grid-template-columns:1fr;margin-top:28px}.sidebar{position:static}.main-nav,.tag-nav{display:flex;overflow:auto}.nav-item{min-width:max-content}.bookmark-grid{grid-template-columns:1fr}.collection-head h1{font-size:36px}.sidebar-label{margin-top:18px}.tag-nav{padding-bottom:5px}}
@media(max-width:560px){.topbar{padding:0 4vw}.app-shell{width:92vw;gap:28px}.url-row,.new-tag-row{display:block}.url-row .button,.new-tag-row .button{width:100%;margin-top:8px}.preview-row{grid-template-columns:1fr}.dialog-actions,.dialog-actions.split{flex-direction:column}.dialog-actions .button{width:100%}}

